using System.Globalization;

namespace KillerPdf.Engine.Fonts;

internal static class PdfStandardGlyphBounds
{
    private static readonly Dictionary<string, Dictionary<string, (PdfGlyphBounds Bounds, double Width)>> Fonts = Read();
    internal static PdfGlyphBounds? Get(string font, string glyph) =>
        Fonts.TryGetValue(font, out var glyphs) && glyphs.TryGetValue(glyph, out var metrics) ? metrics.Bounds : null;
    internal static double? Width(string font, string glyph) =>
        Fonts.TryGetValue(font, out var glyphs) && glyphs.TryGetValue(glyph, out var metrics) ? metrics.Width : null;

    private static Dictionary<string, Dictionary<string, (PdfGlyphBounds Bounds, double Width)>> Read()
    {
        var result = new Dictionary<string, Dictionary<string, (PdfGlyphBounds Bounds, double Width)>>(StringComparer.Ordinal);
        foreach (string line in Data.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var fields = line.Trim().Split(';');
            var glyphs = new Dictionary<string, (PdfGlyphBounds Bounds, double Width)>(StringComparer.Ordinal);
            foreach (string item in fields[1].Split(' '))
            {
                var pair = item.Split('=');
                var box = pair[1].Split(',').Select(s => double.Parse(s, CultureInfo.InvariantCulture)).ToArray();
                glyphs[pair[0]] = (new PdfGlyphBounds(box[0], box[1], box[2], box[3]), box[4]);
            }
            result[fields[0]] = glyphs;
        }
        return result;
    }

